import { ListItem } from '@tiptap/extension-list'
import { Placeholder } from '@tiptap/extensions'
import { type Editor, EditorContent, Extension, useEditor, useEditorState } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import { useContext, useEffect, useId, useMemo, useRef, useState } from 'react'
import { View, getConfig } from 'tamagui/unstyled'
import { FieldContext, useFieldControl } from '../../hooks/useFieldControl'
import { fieldBoxStyle } from '../input/Input'
import { useControllableState } from '../../hooks/useControllableState'
import { normalizeHtml } from './html'
import {
  type ActiveTools,
  LinkBar,
  type RichTextEditorProps,
  type RichTextTool,
  RichTextToolbar,
  contentCss,
  defaultRichTextTools,
  resolveLabels,
  sizePx,
} from './parts'

// Tab leaves the text instead of nesting list items, so the keyboard can
// always move on, and lists stay one level deep, as Rich Text Content draws them.
const FlatListItem = ListItem.extend({
  addKeyboardShortcuts() {
    return { Enter: () => this.editor.commands.splitListItem(this.name) }
  },
})

const toggles: Record<Exclude<RichTextTool, 'link'>, (editor: Editor) => void> = {
  bold: (editor) => editor.chain().focus().toggleBold().run(),
  italic: (editor) => editor.chain().focus().toggleItalic().run(),
  underline: (editor) => editor.chain().focus().toggleUnderline().run(),
  strikethrough: (editor) => editor.chain().focus().toggleStrike().run(),
  code: (editor) => editor.chain().focus().toggleCode().run(),
  heading: (editor) => editor.chain().focus().toggleHeading({ level: 2 }).run(),
  bulletList: (editor) => editor.chain().focus().toggleBulletList().run(),
  orderedList: (editor) => editor.chain().focus().toggleOrderedList().run(),
  quote: (editor) => editor.chain().focus().toggleBlockquote().run(),
}

const activeTools = (editor: Editor): ActiveTools => ({
  bold: editor.isActive('bold'),
  italic: editor.isActive('italic'),
  underline: editor.isActive('underline'),
  strikethrough: editor.isActive('strike'),
  code: editor.isActive('code'),
  link: editor.isActive('link'),
  heading: editor.isActive('heading'),
  bulletList: editor.isActive('bulletList'),
  orderedList: editor.isActive('orderedList'),
  quote: editor.isActive('blockquote'),
})

const fieldFocusStyle = {
  borderColor: 'ring',
  outlineColor: 'ring',
  outlineStyle: 'solid',
  outlineWidth: '2px',
} as const

/** The theme as CSS variables, so the text follows a theme change without a render. */
function editorCss() {
  const fonts = getConfig().fonts as Record<string, { family?: string } | undefined>
  return contentCss(
    '.aui-rich-text',
    {
      text: 'var(--foreground)',
      muted: 'var(--mutedForeground)',
      link: 'var(--primaryText)',
      border: 'var(--border)',
      code: 'var(--muted)',
      placeholder: 'var(--placeholder-color)',
    },
    { body: fonts.body?.family ?? 'sans-serif', mono: fonts.mono?.family ?? 'monospace' },
  )
}

/**
 * A WYSIWYG editor: the text shows bold, headings, lists and links as it is
 * written. It saves HTML, which Rich Text Content shows on every platform.
 * Web edits in the page with TipTap; iOS and Android run TipTap in a WebView
 * (TenTap), with the same toolbar.
 */
export function RichTextEditor(editorProps: RichTextEditorProps) {
  const field = useContext(FieldContext)
  const {
    value: valueProp,
    defaultValue = '',
    onValueChange,
    placeholder,
    tools = defaultRichTextTools,
    minHeight = '32',
    disabled = false,
    invalid = false,
    id,
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    'aria-describedby': ariaDescribedBy,
    'aria-required': ariaRequired,
    labels: labelsProp,
  } = useFieldControl(editorProps)
  const labels = resolveLabels(labelsProp)
  const css = useMemo(editorCss, [])
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  })
  // The address the link field opens with, or null while it is closed.
  const [link, setLink] = useState<string | null>(null)
  const generatedId = useId()
  const textId = id ?? `${generatedId}-text`
  // The HTML the editor wrote last, so it is not loaded back into the editor.
  const written = useRef(value)
  const latest = useRef({ setValue, placeholder, openLink: () => {} })

  const extensions = useMemo(
    () => [
      StarterKit.configure({
        codeBlock: false,
        horizontalRule: false,
        listItem: false,
        trailingNode: false,
        heading: { levels: [1, 2, 3] },
        link: { openOnClick: false, autolink: true, defaultProtocol: 'https' },
      }),
      FlatListItem,
      Placeholder.configure({ placeholder: () => latest.current.placeholder ?? '' }),
      Extension.create({
        name: 'advuiLinkShortcut',
        addKeyboardShortcuts: () => ({
          'Mod-k': () => {
            latest.current.openLink()
            return true
          },
        }),
      }),
    ],
    [],
  )

  // A `<label for>` cannot name a div, so a Field's label names it by id.
  const labelledBy = ariaLabel ? undefined : (ariaLabelledBy ?? field?.labelId)
  const minPx = sizePx(minHeight)
  const attributes = useMemo(
    () =>
      Object.fromEntries(
        Object.entries({
          id: textId,
          role: 'textbox',
          'aria-multiline': 'true',
          'aria-label': ariaLabel,
          'aria-labelledby': labelledBy,
          'aria-describedby': ariaDescribedBy,
          'aria-invalid': invalid ? 'true' : undefined,
          'aria-required': ariaRequired ? 'true' : undefined,
          'aria-disabled': disabled ? 'true' : undefined,
          'aria-placeholder': placeholder,
          class: 'aui-rich-text',
          style: minPx === undefined ? undefined : `min-height: ${minPx}px`,
        }).filter((entry): entry is [string, string] => entry[1] !== undefined),
      ),
    [
      textId,
      ariaLabel,
      labelledBy,
      ariaDescribedBy,
      invalid,
      ariaRequired,
      disabled,
      placeholder,
      minPx,
    ],
  )
  const editorOptions = useMemo(() => ({ attributes }), [attributes])

  const editor = useEditor({
    // The server and the first render show the frame; TipTap fills it after.
    immediatelyRender: false,
    extensions,
    content: written.current,
    editable: !disabled,
    editorProps: editorOptions,
    onUpdate: ({ editor: current }) => {
      const html = normalizeHtml(current.getHTML())
      if (html === written.current) return
      written.current = html
      latest.current.setValue(html)
    },
  })

  const active: ActiveTools & { focused?: boolean } =
    useEditorState({
      editor,
      selector: ({ editor: current }) =>
        current ? { ...activeTools(current), focused: current.isFocused } : {},
    }) ?? {}

  const openLink = () => {
    if (!editor || disabled) return
    setLink((editor.getAttributes('link').href as string | undefined) ?? 'https://')
  }
  latest.current = { setValue, placeholder, openLink }

  // A new value from outside: load it, without calling onValueChange back.
  useEffect(() => {
    if (!editor || value === written.current) return
    written.current = value
    editor.commands.setContent(value, { emitUpdate: false })
  }, [editor, value])

  useEffect(() => {
    if (editor && editor.isEditable === disabled) editor.setEditable(!disabled, false)
  }, [editor, disabled])

  const closeLink = () => {
    setLink(null)
    editor?.commands.focus()
  }
  const applyLink = (href: string) => {
    setLink(null)
    if (!editor) return
    const chain = editor.chain().focus()
    // With nothing selected outside a link, the address is the text.
    if (editor.state.selection.empty && !editor.isActive('link')) {
      chain.insertContent({ type: 'text', text: href, marks: [{ type: 'link', attrs: { href } }] })
    } else chain.extendMarkRange('link').setLink({ href })
    chain.run()
  }

  return (
    <View
      {...fieldBoxStyle}
      // The text is focused, not the frame: draw the field's focus ring for it.
      {...(active.focused && fieldFocusStyle)}
      {...(invalid && { borderColor: 'error' })}
      opacity={disabled ? 0.5 : 1}
      overflow="hidden"
      width="100%"
    >
      <style href="advui-rich-text" precedence="default">
        {css}
      </style>
      <RichTextToolbar
        tools={tools}
        labels={labels}
        active={{ ...active, link: active.link || link !== null }}
        disabled={disabled}
        // The text exists once TipTap has mounted, after the first render.
        controls={editor ? textId : undefined}
        onTool={(tool) => {
          if (!editor) return
          if (tool === 'link') {
            if (link === null) openLink()
            else closeLink()
          } else toggles[tool](editor)
        }}
      />
      {link !== null ? (
        <LinkBar
          labels={labels}
          initial={link}
          linked={!!active.link}
          onApply={applyLink}
          onRemove={() => {
            setLink(null)
            editor?.chain().focus().extendMarkRange('link').unsetLink().run()
          }}
          onCancel={closeLink}
        />
      ) : null}
      <View minHeight={minHeight}>
        <EditorContent editor={editor} />
      </View>
    </View>
  )
}

import {
  BlockquoteBridge,
  BoldBridge,
  BulletListBridge,
  CodeBridge,
  CoreBridge,
  HardBreakBridge,
  HeadingBridge,
  HistoryBridge,
  ItalicBridge,
  LinkBridge,
  ListItemBridge,
  OrderedListBridge,
  PlaceholderBridge,
  RichText,
  StrikeBridge,
  UnderlineBridge,
  useBridgeState,
  useEditorBridge,
} from '@10play/tentap-editor'
import { useEffect, useRef, useState } from 'react'
import { View, useTheme } from 'tamagui/unstyled'
import { fieldBoxStyle } from '../input/Input'
import { useControllableState } from '../../hooks/useControllableState'
import { useFieldControl } from '../../hooks/useFieldControl'
import { escapeHtml, normalizeHtml } from './html'
import {
  type ActiveTools,
  LinkBar,
  type RichTextEditorProps,
  type RichTextTool,
  RichTextToolbar,
  contentCss,
  defaultRichTextTools,
  resolveLabels,
  sizePx,
} from './parts'

type Bridge = ReturnType<typeof useEditorBridge>

const toggles: Record<Exclude<RichTextTool, 'link'>, (editor: Bridge) => void> = {
  bold: (editor) => editor.toggleBold(),
  italic: (editor) => editor.toggleItalic(),
  underline: (editor) => editor.toggleUnderline(),
  strikethrough: (editor) => editor.toggleStrike(),
  code: (editor) => editor.toggleCode(),
  heading: (editor) => editor.toggleHeading(2),
  bulletList: (editor) => editor.toggleBulletList(),
  orderedList: (editor) => editor.toggleOrderedList(),
  quote: (editor) => editor.toggleBlockquote(),
}

// Sets (or, for undefined, removes) attributes of the editable element.
const attributesScript = (attributes: Record<string, string | undefined>) =>
  `(function () {
  var el = document.querySelector('.ProseMirror');
  if (!el) return;
  var attributes = ${JSON.stringify(attributes)};
  Object.keys(attributes).forEach(function (name) {
    if (attributes[name] === undefined || attributes[name] === null) el.removeAttribute(name);
    else el.setAttribute(name, attributes[name]);
  });
})();
true;`

export function RichTextEditor(editorProps: RichTextEditorProps) {
  const {
    value: valueProp,
    defaultValue = '',
    onValueChange,
    placeholder,
    tools = defaultRichTextTools,
    minHeight = '32',
    disabled = false,
    invalid = false,
    'aria-label': ariaLabel,
    'aria-required': ariaRequired,
    accessibilityHint,
    labels: labelsProp,
  } = useFieldControl(editorProps)
  const labels = resolveLabels(labelsProp)
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  })
  const [link, setLink] = useState<string | null>(null)
  // The link field takes focus from the WebView, and Android then collapses
  // the editor's selection, so the field keeps the one it opened with.
  const opened = useRef({ from: 0, to: 0, linked: false })
  const written = useRef(value)
  const latest = useRef(setValue)
  latest.current = setValue

  const editor = useEditorBridge({
    initialContent: value,
    editable: !disabled,
    // The WebView grows with the text, inside the screen's own scrolling.
    dynamicHeight: true,
    avoidIosKeyboard: true,
    bridgeExtensions: [
      CoreBridge,
      BoldBridge,
      ItalicBridge,
      UnderlineBridge,
      StrikeBridge,
      CodeBridge,
      LinkBridge.configureExtension({ openOnClick: false, autolink: true }),
      HeadingBridge,
      BulletListBridge,
      OrderedListBridge,
      ListItemBridge,
      BlockquoteBridge,
      HistoryBridge,
      HardBreakBridge,
      PlaceholderBridge.configureExtension({ placeholder: placeholder ?? '' }),
    ],
    theme: { webview: { backgroundColor: 'transparent' } },
    onChange: () => {
      void editor.getHTML().then((raw) => {
        const html = normalizeHtml(raw)
        if (html === written.current) return
        written.current = html
        latest.current(html)
      })
    },
  })
  const state = useBridgeState(editor)

  // The WebView is a page of its own: give it the theme's values, again on a theme change.
  const theme = useTheme()
  const color = (key: string) => (theme[key as keyof typeof theme] as { val?: string })?.val ?? ''
  const minPx = sizePx(minHeight)
  const css =
    contentCss(
      '.ProseMirror',
      {
        text: color('foreground'),
        muted: color('mutedForeground'),
        link: color('primaryText'),
        border: color('border'),
        code: color('muted'),
        placeholder: color('placeholder-color'),
      },
      // App fonts are not loaded in the WebView; the system's are its default.
      { body: 'system-ui, sans-serif', mono: 'monospace' },
    ) + (minPx === undefined ? '' : `.ProseMirror { min-height: ${minPx}px; }`)
  useEffect(() => {
    editor.injectCSS(css, 'advui-rich-text')
  }, [editor, css])

  // The name and state, for TalkBack and VoiceOver, are read from the page.
  useEffect(() => {
    if (!state.isReady) return
    editor.injectJS(
      attributesScript({
        'aria-label': ariaLabel,
        'aria-description': accessibilityHint,
        'aria-invalid': invalid ? 'true' : undefined,
        'aria-required': ariaRequired ? 'true' : undefined,
      }),
    )
  }, [editor, state.isReady, ariaLabel, accessibilityHint, invalid, ariaRequired])

  useEffect(() => {
    if (state.isReady) editor.setPlaceholder(placeholder ?? '')
  }, [editor, state.isReady, placeholder])

  // A new value from outside: load it, without calling onValueChange back.
  useEffect(() => {
    if (value === written.current) return
    written.current = value
    editor.setContent(value, { emitUpdate: false })
  }, [editor, value])

  const active: ActiveTools = {
    bold: state.isBoldActive,
    italic: state.isItalicActive,
    underline: state.isUnderlineActive,
    strikethrough: state.isStrikeActive,
    code: state.isCodeActive,
    link: state.isLinkActive || link !== null,
    heading: state.headingLevel !== undefined,
    bulletList: state.isBulletListActive,
    orderedList: state.isOrderedListActive,
    quote: state.isBlockquoteActive,
  }

  const closeLink = () => {
    setLink(null)
    editor.setSelection(opened.current.from, opened.current.to)
    editor.focus(null)
  }
  const openLink = () => {
    const { from, to } = state.selection
    opened.current = { from, to, linked: state.isLinkActive }
    setLink(state.activeLink ?? 'https://')
  }
  const applyLink = (href: string) => {
    setLink(null)
    const { from, to, linked } = opened.current
    editor.setSelection(from, to)
    // With nothing selected outside a link, the address is the text.
    if (from === to && !linked) {
      editor.insertContent(`<a href="${escapeHtml(href)}">${escapeHtml(href)}</a>`)
    } else editor.setLink(href)
    editor.focus(null)
  }
  const removeLink = () => {
    setLink(null)
    editor.setSelection(opened.current.from, opened.current.to)
    // TenTap unsets the link around the selection for '' and ignores null (a cancel).
    editor.setLink('')
    editor.focus(null)
  }

  return (
    <View
      {...fieldBoxStyle}
      {...(state.isFocused && { borderColor: 'ring' })}
      {...(invalid && { borderColor: 'error' })}
      opacity={disabled ? 0.5 : 1}
      overflow="hidden"
      width="100%"
    >
      <RichTextToolbar
        tools={tools}
        labels={labels}
        active={active}
        disabled={disabled}
        onTool={(tool) => {
          if (tool !== 'link') return toggles[tool](editor)
          if (link === null) openLink()
          else closeLink()
        }}
      />
      {link !== null ? (
        <LinkBar
          labels={labels}
          initial={link}
          linked={opened.current.linked}
          onApply={applyLink}
          onRemove={removeLink}
          onCancel={closeLink}
        />
      ) : null}
      <View minHeight={minHeight}>
        <RichText editor={editor} />
      </View>
    </View>
  )
}

import { useMemo } from 'react'
import { type GetProps, View } from 'tamagui/unstyled'
import { ContentBlocks } from '../markdown-editor/MarkdownContent'
import { parseHtml } from './html'

export interface RichTextContentProps extends Omit<GetProps<typeof View>, 'children'> {
  /** HTML, as written by Rich Text Editor. */
  children: string
  /** Added to heading levels: with 0 (default), the editor's headings stay `h2`. */
  headingOffset?: number
}

/**
 * Shows HTML written with Rich Text Editor, with the same styles on every
 * platform. It draws the HTML as views instead of setting it as markup, so
 * scripts and styles in it never run.
 */
export function RichTextContent({ children, headingOffset = 0, ...props }: RichTextContentProps) {
  const blocks = useMemo(() => parseHtml(children), [children])
  return (
    <View gap="3" {...props}>
      <ContentBlocks blocks={blocks} headingOffset={headingOffset} />
    </View>
  )
}

import {
  BoldIcon,
  CodeIcon,
  HeadingIcon,
  ItalicIcon,
  LinkIcon,
  ListIcon,
  ListOrderedIcon,
  QuoteIcon,
  StrikethroughIcon,
  UnderlineIcon,
} from '@advui/icons'
import { type ReactElement, useState } from 'react'
import { type GetProps, type View, XStack, getConfig, getTokenValue, isWeb } from 'tamagui/unstyled'
import { Button } from '../button/Button'
import { FieldContext } from '../../hooks/useFieldControl'
import { Input } from '../input/Input'
import { Toggle } from '../toggle/Toggle'
import { Toolbar } from '../toolbar/Toolbar'

export type RichTextTool =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strikethrough'
  | 'code'
  | 'link'
  | 'heading'
  | 'bulletList'
  | 'orderedList'
  | 'quote'

export interface RichTextEditorLabels {
  toolbar: string
  tools: Record<RichTextTool, string>
  /** The link field's name. */
  linkAddress: string
  applyLink: string
  removeLink: string
  cancel: string
}

const defaultLabels: RichTextEditorLabels = {
  toolbar: 'Formatting',
  tools: {
    bold: 'Bold',
    italic: 'Italic',
    underline: 'Underline',
    strikethrough: 'Strikethrough',
    code: 'Code',
    link: 'Link',
    heading: 'Heading',
    bulletList: 'Bulleted list',
    orderedList: 'Numbered list',
    quote: 'Quote',
  },
  linkAddress: 'Link address',
  applyLink: 'Apply',
  removeLink: 'Remove link',
  cancel: 'Cancel',
}

export const defaultRichTextTools: RichTextTool[] = [
  'bold',
  'italic',
  'underline',
  'strikethrough',
  'heading',
  'bulletList',
  'orderedList',
  'quote',
  'link',
  'code',
]

export interface RichTextEditorProps {
  /** HTML (controlled). An empty document is `''`. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  placeholder?: string
  /** Toolbar buttons, in order. Default: all ten. */
  tools?: RichTextTool[]
  /** Minimum height of the text. Default: `32`. */
  minHeight?: GetProps<typeof View>['minHeight']
  disabled?: boolean
  invalid?: boolean
  id?: string
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
  'aria-required'?: boolean
  /** Native: help read after the name (a Field sets it). */
  accessibilityHint?: string
  /** Toolbar, tool and link field names, for translation. */
  labels?: Partial<Omit<RichTextEditorLabels, 'tools'>> & {
    tools?: Partial<RichTextEditorLabels['tools']>
  }
}

export function resolveLabels(labels: RichTextEditorProps['labels']): RichTextEditorLabels {
  return { ...defaultLabels, ...labels, tools: { ...defaultLabels.tools, ...labels?.tools } }
}

/** Which tools the selection has, so the toolbar shows them pressed. */
export type ActiveTools = Partial<Record<RichTextTool, boolean>>

const icons: Record<RichTextTool, ReactElement> = {
  bold: <BoldIcon />,
  italic: <ItalicIcon />,
  underline: <UnderlineIcon />,
  strikethrough: <StrikethroughIcon />,
  code: <CodeIcon />,
  link: <LinkIcon />,
  heading: <HeadingIcon />,
  bulletList: <ListIcon />,
  orderedList: <ListOrderedIcon />,
  quote: <QuoteIcon />,
}

// TipTap's shortcuts, plus Mod-K for links (web).
const shortcuts: Record<RichTextTool, string> = {
  bold: 'B',
  italic: 'I',
  underline: 'U',
  strikethrough: 'Shift+S',
  code: 'E',
  link: 'K',
  heading: 'Alt+2',
  bulletList: 'Shift+8',
  orderedList: 'Shift+7',
  quote: 'Shift+B',
}

export function RichTextToolbar({
  tools,
  labels,
  active,
  disabled,
  controls,
  onTool,
}: {
  tools: RichTextTool[]
  labels: RichTextEditorLabels
  active: ActiveTools
  disabled: boolean
  /** The text's id. */
  controls?: string
  onTool: (tool: RichTextTool) => void
}) {
  return (
    <Toolbar
      variant="ghost"
      size="sm"
      wrap
      gap="0-5"
      padding="1"
      borderRadius={0}
      borderBottomWidth={1}
      borderColor="border"
      // A named frame on native catches touches meant for its buttons.
      {...(isWeb && { role: 'toolbar', 'aria-label': labels.toolbar, 'aria-controls': controls })}
    >
      {tools.map((tool) => (
        <Toggle
          key={tool}
          size="sm"
          icon={icons[tool]}
          aria-label={labels.tools[tool]}
          pressed={!!active[tool]}
          disabled={disabled}
          {...(isWeb && {
            title: `${labels.tools[tool]} (Ctrl+${shortcuts[tool]})`,
            'aria-keyshortcuts': `Control+${shortcuts[tool]} Meta+${shortcuts[tool]}`,
          })}
          onPress={() => onTool(tool)}
        />
      ))}
    </Toolbar>
  )
}

/** The address field Link opens under the toolbar. */
export function LinkBar({
  labels,
  initial,
  linked,
  onApply,
  onRemove,
  onCancel,
}: {
  labels: RichTextEditorLabels
  initial: string
  /** The selection is in a link already. */
  linked: boolean
  onApply: (href: string) => void
  onRemove: () => void
  onCancel: () => void
}) {
  const [href, setHref] = useState(initial)
  const apply = () => {
    const url = href.trim()
    if (url && url !== 'https://') onApply(url)
    else onCancel()
  }
  return (
    // The field is not the editor's: keep a surrounding Field's id and label off it.
    <FieldContext.Provider value={null}>
      <XStack
        flexWrap="wrap"
        alignItems="center"
        gap="2"
        padding="2"
        borderBottomWidth={1}
        borderColor="border"
      >
        <Input
          size="sm"
          flex={1}
          minWidth="40"
          autoFocus
          value={href}
          onChangeText={setHref}
          aria-label={labels.linkAddress}
          inputMode="url"
          autoCapitalize="none"
          autoCorrect={false}
          {...(isWeb
            ? {
                onKeyDown: (event: { key: string; preventDefault: () => void }) => {
                  if (event.key !== 'Enter' && event.key !== 'Escape') return
                  event.preventDefault()
                  if (event.key === 'Enter') apply()
                  else onCancel()
                },
              }
            : { keyboardType: 'url', returnKeyType: 'done', onSubmitEditing: apply })}
        />
        <Button size="sm" onPress={apply}>
          {labels.applyLink}
        </Button>
        {linked ? (
          <Button size="sm" variant="ghost" onPress={onRemove}>
            {labels.removeLink}
          </Button>
        ) : null}
        <Button size="sm" variant="ghost" onPress={onCancel}>
          {labels.cancel}
        </Button>
      </XStack>
    </FieldContext.Provider>
  )
}

/** Theme colors for `contentCss`: CSS variables on web, values on native. */
export interface ContentColors {
  text: string
  muted: string
  link: string
  border: string
  code: string
  placeholder: string
}

type FontConfig = {
  family?: string
  size: Record<string, number>
  lineHeight: Record<string, number>
}

/** A size token's pixels, for CSS. */
export const sizePx = (size: RichTextEditorProps['minHeight']) =>
  typeof size === 'number' ? size : (getTokenValue(size as never, 'size') as number | undefined)

/**
 * Styles the HTML being edited the way Rich Text Content draws it, from the
 * theme's tokens: TipTap edits real HTML, which Tamagui does not style.
 */
export function contentCss(
  scope: string,
  colors: ContentColors,
  families: { body: string; mono: string },
) {
  const fonts = getConfig().fonts as Record<string, FontConfig>
  const body = fonts.body!
  const mono = fonts.mono ?? body
  const space = (token: string) => `${getTokenValue(token as never, 'space')}px`
  const type = (font: FontConfig, step: string) =>
    `font-size: ${font.size[step]}px; line-height: ${font.lineHeight[step]}px;`
  return `
${scope} { color: ${colors.text}; font-family: ${families.body}; ${type(body, '2')} padding: ${space('3')}; outline: none; white-space: pre-wrap; overflow-wrap: break-word; }
${scope} :where(p, h1, h2, h3, h4, h5, h6, ul, ol, li, blockquote) { margin: 0; }
${scope} > * + *, ${scope} blockquote > * + * { margin-top: ${space('3')}; }
${scope} h1, ${scope} h2, ${scope} h3, ${scope} h4, ${scope} h5, ${scope} h6 { font-weight: 600; }
${scope} h1 { ${type(body, '5')} }
${scope} h2 { ${type(body, '4')} }
${scope} h3, ${scope} h4, ${scope} h5, ${scope} h6 { ${type(body, '3')} }
${scope} ul, ${scope} ol { padding-inline-start: ${space('6')}; }
${scope} li + li { margin-top: ${space('1')}; }
${scope} li::marker { color: ${colors.muted}; }
${scope} blockquote { border-inline-start: 3px solid ${colors.border}; padding-inline-start: ${space('3')}; }
${scope} code { font-family: ${families.mono}; ${type(mono, '2')} background-color: ${colors.code}; border-radius: ${getTokenValue('xs' as never, 'radius')}px; padding: 0 ${space('1')}; }
${scope} a { color: ${colors.link}; text-decoration: underline; }
${scope} p.is-editor-empty:first-child::before { content: attr(data-placeholder); color: ${colors.placeholder}; float: left; height: 0; pointer-events: none; }
`
}

import { type BlockNode, type InlineNode, safeHref } from '../markdown-editor/markdown'

/**
 * Reads the HTML Rich Text Editor writes (TipTap's `p`, `h1`–`h6`, `strong`,
 * `em`, `u`, `s`, `code`, `a`, `ul`, `ol`, `li`, `blockquote` and `br`) into
 * the blocks both viewers draw. It builds no DOM, so it runs on iOS and
 * Android too, and nothing in the HTML runs: scripts and styles are dropped
 * with their content, other tags keep only their text, and links keep only
 * `http(s)` and `mailto` addresses.
 */

type HtmlElement = { tag: string; attrs: Record<string, string>; children: HtmlNode[] }
type HtmlNode = HtmlElement | string

const voidTags = new Set([
  'area',
  'base',
  'br',
  'col',
  'embed',
  'hr',
  'img',
  'input',
  'link',
  'meta',
  'source',
  'track',
  'wbr',
])
// Dropped with everything inside them.
const skippedTags = new Set([
  'head',
  'iframe',
  'math',
  'noscript',
  'object',
  'script',
  'select',
  'style',
  'svg',
  'template',
  'textarea',
  'title',
])
const headings: Record<string, number> = { h1: 1, h2: 2, h3: 3, h4: 4, h5: 5, h6: 6 }
const marks: Record<string, 'bold' | 'italic' | 'strike' | 'underline'> = {
  b: 'bold',
  strong: 'bold',
  em: 'italic',
  i: 'italic',
  del: 'strike',
  s: 'strike',
  strike: 'strike',
  ins: 'underline',
  u: 'underline',
}
const codeTags = new Set(['code', 'kbd', 'samp'])
// Tags that start a new block. Containers among them (div, section…) hold
// paragraphs of their own; the rest are read below.
const blockTags = new Set([
  ...Object.keys(headings),
  'address',
  'article',
  'aside',
  'blockquote',
  'dd',
  'details',
  'div',
  'dl',
  'dt',
  'figcaption',
  'figure',
  'footer',
  'header',
  'hr',
  'li',
  'main',
  'nav',
  'ol',
  'p',
  'pre',
  'section',
  'summary',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'tr',
  'ul',
])

const entities: Record<string, string> = {
  amp: '&',
  apos: "'",
  gt: '>',
  lt: '<',
  nbsp: ' ',
  quot: '"',
}

export function decodeEntities(text: string) {
  return text.replace(/&(#x[\da-f]+|#\d+|[a-z]+);/gi, (match, code: string) => {
    if (code[0] !== '#') return entities[code.toLowerCase()] ?? match
    const hex = code[1] === 'x' || code[1] === 'X'
    const point = parseInt(code.slice(hex ? 2 : 1), hex ? 16 : 10)
    return point > 0 && point <= 0x10ffff ? String.fromCodePoint(point) : match
  })
}

/** Escapes text for HTML, such as a link's address and text. */
export function escapeHtml(text: string) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

/** TipTap writes `<p></p>` for an empty document; that is saved as `''`. */
export function normalizeHtml(html: string) {
  return /^(\s|<p>(\s|<br\s*\/?>)*<\/p>)*$/i.test(html) ? '' : html
}

function parseAttrs(source: string) {
  const attrs: Record<string, string> = {}
  for (const match of source.matchAll(
    /([^\s=/"'<>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g,
  ))
    attrs[match[1]!.toLowerCase()] = decodeEntities(match[2] ?? match[3] ?? match[4] ?? '')
  return attrs
}

/** A tree of the tags; a closing tag closes any still open inside it. */
function parseTree(html: string): HtmlNode[] {
  const root: HtmlElement = { tag: '', attrs: {}, children: [] }
  const open = [root]
  let skipping: string | null = null
  const tokens =
    /<!--[\s\S]*?(?:-->|$)|<(\/?)([a-z][a-z0-9-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>|([^<]+|<)/gi
  for (const [, closing, name, attrs = '', text] of html.matchAll(tokens)) {
    if (text !== undefined) {
      if (!skipping) open[open.length - 1]!.children.push(decodeEntities(text))
      continue
    }
    // A comment.
    if (!name) continue
    const tag = name.toLowerCase()
    if (skipping) {
      if (closing && tag === skipping) skipping = null
      continue
    }
    if (closing) {
      for (let i = open.length - 1; i > 0; i--) {
        if (open[i]!.tag !== tag) continue
        open.length = i
        break
      }
      continue
    }
    const selfClosing = attrs.trimEnd().endsWith('/')
    if (skippedTags.has(tag)) {
      if (!selfClosing) skipping = tag
      continue
    }
    const element: HtmlElement = { tag, attrs: parseAttrs(attrs), children: [] }
    open[open.length - 1]!.children.push(element)
    if (!voidTags.has(tag) && !selfClosing) open.push(element)
  }
  return root.children
}

const textOf = (nodes: HtmlNode[]): string =>
  nodes.map((node) => (typeof node === 'string' ? node : textOf(node.children))).join('')

/** Text and marks; blocks inside (paragraphs in a list item) become lines. */
function toInline(nodes: HtmlNode[]): InlineNode[] {
  const result: InlineNode[] = []
  const line = () => {
    const last = result[result.length - 1]
    if (last && !(last.type === 'text' && last.text.endsWith('\n'))) {
      result.push({ type: 'text', text: '\n' })
    }
  }
  for (const node of nodes) {
    if (typeof node === 'string') {
      // HTML collapses runs of white space; no-break spaces stay.
      result.push({ type: 'text', text: node.replace(/[ \t\n\r\f]+/g, ' ') })
      continue
    }
    const { tag, attrs, children } = node
    if (tag === 'br') result.push({ type: 'text', text: '\n' })
    else if (codeTags.has(tag)) result.push({ type: 'code', text: textOf(children) })
    else if (marks[tag]) result.push({ type: marks[tag], children: toInline(children) })
    else if (tag === 'a') {
      const href = safeHref(attrs.href ?? '')
      if (href) result.push({ type: 'link', href, children: toInline(children) })
      else result.push(...toInline(children))
    } else if (blockTags.has(tag)) {
      line()
      result.push(...toInline(children))
      line()
    } else result.push(...toInline(children))
  }
  return result
}

/** Drops the white space at the ends; null when nothing is left to show. */
function trimInline(nodes: InlineNode[]): InlineNode[] | null {
  const trimmed = [...nodes]
  const trimText = (index: number, pattern: RegExp) => {
    const node = trimmed[index]
    if (node?.type !== 'text') return false
    const text = node.text.replace(pattern, '')
    if (text) trimmed[index] = { type: 'text', text }
    else trimmed.splice(index, 1)
    return !text
  }
  while (trimmed.length && trimText(0, /^[ \n]+/));
  while (trimmed.length && trimText(trimmed.length - 1, /[ \n]+$/));
  const visible = (node: InlineNode): boolean =>
    node.type === 'text' || node.type === 'code'
      ? node.text.trim() !== ''
      : node.children.some(visible)
  return trimmed.some(visible) ? trimmed : null
}

function toBlocks(nodes: HtmlNode[]): BlockNode[] {
  const blocks: BlockNode[] = []
  let run: HtmlNode[] = []
  const flush = () => {
    const children = trimInline(toInline(run))
    if (children) blocks.push({ type: 'paragraph', children })
    run = []
  }
  for (const node of nodes) {
    if (typeof node === 'string' || !blockTags.has(node.tag)) {
      run.push(node)
      continue
    }
    flush()
    const { tag, attrs, children } = node
    if (headings[tag]) {
      const inline = trimInline(toInline(children))
      if (inline) blocks.push({ type: 'heading', level: headings[tag], children: inline })
    } else if (tag === 'blockquote') {
      const inner = toBlocks(children)
      if (inner.length) blocks.push({ type: 'quote', children: inner })
    } else if (tag === 'ul' || tag === 'ol') {
      const items = listItems(children)
      if (items.length) {
        const start = parseInt(attrs.start ?? '', 10)
        blocks.push({
          type: 'list',
          ordered: tag === 'ol',
          start: tag === 'ol' && start > 0 ? start : 1,
          items,
        })
      }
    } else if (tag === 'pre') {
      blocks.push({ type: 'paragraph', children: [{ type: 'code', text: textOf(children) }] })
    } else if (tag !== 'hr') blocks.push(...toBlocks(children))
  }
  flush()
  return blocks
}

const isList = (node: HtmlNode): node is HtmlElement =>
  typeof node !== 'string' && (node.tag === 'ul' || node.tag === 'ol')

/** One line per item. Lists nested in an item follow it in the same list. */
function listItems(nodes: HtmlNode[]): InlineNode[][] {
  const items: InlineNode[][] = []
  for (const node of nodes) {
    if (typeof node === 'string') continue
    if (node.tag === 'ul' || node.tag === 'ol') {
      items.push(...listItems(node.children))
      continue
    }
    const own = trimInline(toInline(node.children.filter((child) => !isList(child))))
    if (own) items.push(own)
    for (const list of node.children.filter(isList)) items.push(...listItems(list.children))
  }
  return items
}

export function parseHtml(html: string): BlockNode[] {
  return toBlocks(parseTree(html))
}

